-- ---------------------------------------------------------------------------
-- 0011_enable_rls.sql
-- ---------------------------------------------------------------------------
-- Supabase exposes every table in the public schema through its REST/GraphQL Data API, authorised by the
-- publishable (anon) key. This application reaches the database only through a server-side Postgres
-- connection (DATABASE_URL, which bypasses RLS), so the Data API must have no access at all.
-- RLS enabled with NO policies = deny for anon/authenticated. Idempotent; also safe on plain PostgreSQL.
DO $$
DECLARE t record;
BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t.tablename);
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon;
    REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon;
    ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM anon;
    ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON ALL TABLES IN SCHEMA public FROM authenticated;
    REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM authenticated;
    ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM authenticated;
    ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM authenticated;
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- 0012_login_attempts.sql
-- ---------------------------------------------------------------------------
-- Failed/successful admin sign-in attempts, used for server-side brute-force throttling.
-- Run AFTER 0011. RLS is enabled with no policies so the Supabase Data API cannot read it.
CREATE TABLE IF NOT EXISTS login_attempts (
  id          SERIAL PRIMARY KEY,
  email       VARCHAR(200) NOT NULL,
  ip          VARCHAR(64)  NOT NULL DEFAULT '',
  succeeded   BOOLEAN      NOT NULL DEFAULT FALSE,
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS ix_login_attempts_email      ON login_attempts (email);
CREATE INDEX IF NOT EXISTS ix_login_attempts_ip         ON login_attempts (ip);
CREATE INDEX IF NOT EXISTS ix_login_attempts_created_at ON login_attempts (created_at);
ALTER TABLE login_attempts ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON TABLE login_attempts FROM anon;
    REVOKE ALL ON SEQUENCE login_attempts_id_seq FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON TABLE login_attempts FROM authenticated;
    REVOKE ALL ON SEQUENCE login_attempts_id_seq FROM authenticated;
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- 0013_storage_buckets.sql
-- ---------------------------------------------------------------------------
-- Supabase Storage buckets used by the application. Safe to run on plain PostgreSQL: it does nothing when the
-- Supabase `storage` schema is absent, and it never changes a bucket that already exists.
--   vora-media      PUBLIC  read: website illustrations and article images uploaded in the admin portal.
--   vora-documents  PRIVATE     : manually stamped receipts and customer-signed quotation approvals.
-- The application reaches both buckets with the server-side service-role key (which bypasses storage RLS), so
-- no storage.objects policies are created: anonymous and authenticated API clients get no write access at all.
DO $$
BEGIN
  IF to_regclass('storage.buckets') IS NULL THEN
    RAISE NOTICE 'storage schema not present; create buckets vora-media (public) and vora-documents (private) manually';
    RETURN;
  END IF;
  BEGIN
    INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    VALUES ('vora-media', 'vora-media', TRUE, 7000000, ARRAY['image/png', 'image/jpeg', 'image/webp', 'image/avif']),
           ('vora-documents', 'vora-documents', FALSE, 10485760, ARRAY['application/pdf'])
    ON CONFLICT (id) DO NOTHING;
  EXCEPTION WHEN undefined_column THEN
    -- Older Supabase storage schema without per-bucket limits.
    INSERT INTO storage.buckets (id, name, public)
    VALUES ('vora-media', 'vora-media', TRUE), ('vora-documents', 'vora-documents', FALSE)
    ON CONFLICT (id) DO NOTHING;
  END;
END $$;

